def _comptes_relues(lot_honnete_en_vigueur: object, lot_jumeaux_en_vigueur: object) -> tuple[bool, list, list]:
    rev = lot_honnete_en_vigueur.revision if isinstance(lot_honnete_en_vigueur, Lot) else None
