    n = min(len(hon), len(dep), N_RELUES_PAR_CLASSE)
    epreuve = _nom_epreuve(rev)
    rng = g.generateur_de(g.cle("relu", "lot-decisif", "actions"), entropie)
    desc += sentinelles
    desc += [_action_d("action-d-epreuve-relue", p, classe="honnete", epreuve=epreuve)
