                 for t, e in _tirer(rng, ouverts, N_PLANS_RELUS, "plans d'épreuve relus")]
    comptes = {c: sum(d["composante"] == c for d in desc) for c in COMPOSANTES if any(d["composante"] == c for d in desc)}
